changeSet.sql:
DO $$
DECLARE
    start_month DATE := (date_trunc('month', CURRENT_DATE) - INTERVAL '11 months')::DATE;
    m       INT;
    p_start DATE;
    p_end   DATE;
    p_name  TEXT;
BEGIN
    FOR m IN 0..11 LOOP
        p_start := (start_month + (m || ' months')::INTERVAL)::DATE;
        p_end   := (p_start     + INTERVAL '1 month')::DATE;
        p_name  := 'trades_' || to_char(p_start, 'YYYY_MM');
        EXECUTE format(
            'CREATE TABLE IF NOT EXISTS %I PARTITION OF trades FOR VALUES FROM (%L) TO (%L);',
            p_name, p_start, p_end
        );
    END LOOP;
END $$;

rollback.sql:
DO $$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT inhrelid::regclass AS part_name
        FROM pg_inherits
        WHERE inhparent = 'trades'::regclass
    LOOP
        EXECUTE format('DROP TABLE IF EXISTS %s;', r.part_name);
    END LOOP;
END $$;
